"""REVERSE MODE IN THE IR: the adjoint of a law's step, generated by the compiler and run by the engine.

`lawc --adjoint` turns a term into its adjoint law (src/field/ir/Adjoint.cpp: one reverse sweep over the term's SSA
instructions, stencils to their transposes); `lawc --vjp` runs the primal forward, keeps every state, and runs the
adjoint law backward over them, on the CPU or on CUDA. Checked here:

  transposes    <shift(a), b> = <a, shift_t(b)> and the same for gx/gy/gz and their _t, at the lattice's edges too
  against JAX   the gradient of L = sum(w * V_N) in the initial state and in the params, against jax.grad through the
                law's JAX twin (an independent AD of an independent implementation), for black_scholes.law and heston.law
  greeks        Black-Scholes vega and rho as the totals of sig__adj and r__adj after the backward pass, against the formula
  cost          one backward step against one forward step, on the card (3-D heat, 128^3)

Writes bench/results/adjoint.{json,md}.

    python bench/adjoint.py
"""

import math
import os
import sys
import tempfile

import numpy as np

from common import BUILD, HERE, cuda_available, lawc, read_state, save, write_scene, write_state
import finance as F

import jax
import jax.numpy as jnp

LAWS = os.path.join(HERE, "laws")


def run_vjp(law, grid, start, seed, params, steps, dt, backend, work, term):
    scene = write_scene(os.path.join(work, "v.scene"), grid, [law])
    out = os.path.join(work, f"vjp_{backend}")
    args = ["--scene", scene, "--init", start, "--vjp", seed, "--term", term, "--steps", str(steps), "--dt", repr(dt),
            "--backend", backend, "--dump", out]
    for k, v in params.items():
        args += ["--param", k, repr(v)]
    text = lawc(*args)
    fields, _, _ = read_state(os.path.join(out, "adjoint"))
    line = [l for l in text.splitlines() if l.startswith("vjp of")]
    return fields, line[0] if line else ""


def jax_grads(law_path, grid, state0, weights, params, steps, dt, work, field, wrt_params):
    """jax.grad of sum(w * FIELD after the steps) in the initial FIELD and the params, through the twin."""
    from lawjax.ir import load_law
    scene = write_scene(os.path.join(work, "j.scene"), grid, [law_path])
    ir = os.path.join(work, "j_ir.json")
    lawc("--scene", scene, "--ir-json", ir, "--steps", "0")
    law = load_law(ir, BUILD)
    h = grid[3]
    base = dict(law.param_values)
    base.update(params)
    s0 = {k: jnp.asarray(np.asarray(v, np.float32)) for k, v in state0.items()}
    w = jnp.asarray(weights, jnp.float32)

    def loss(v0, ps):
        p = dict(base)
        p.update(ps)
        s = dict(s0)
        s[field] = v0

        def body(st, _):
            return law.step(st, dt, h, counts=[1] * len(law.terms), params=p), None

        final, _ = jax.lax.scan(body, s, None, length=steps)
        return jnp.sum(w * final[field])

    g_v, g_p = jax.grad(loss, argnums=(0, 1))(s0[field], {k: jnp.float32(base[k]) for k in wrt_params})
    return np.asarray(g_v, np.float64), {k: float(v) for k, v in g_p.items()}


def rel(a, b):
    a, b = np.asarray(a, np.float64), np.asarray(b, np.float64)
    return float(np.max(np.abs(a - b)) / max(np.max(np.abs(b)), 1e-30))


def transposes(work, backend):
    """<op(a), b> against <a, op_t(b)> on a 3-D lattice with odd sizes, edges included."""
    rng = np.random.default_rng(1)
    n = (7, 6, 5)
    a = rng.normal(size=(n[2], n[1], n[0]))
    b = rng.normal(size=(n[2], n[1], n[0]))
    pairs = [("shift(a, 2, 0, -1)", "shift_t(b, 2, 0, -1)"), ("shift(a, -3, 1, 0)", "shift_t(b, -3, 1, 0)"),
             ("gx(a)", "gx_t(b)"), ("gy(a)", "gy_t(b)"), ("gz(a)", "gz_t(b)")]
    lines = ["field a init 0 range -1e30 1e30 static", "field b init 0 range -1e30 1e30 static"]
    for i, (f, t) in enumerate(pairs):
        lines += [f"field f{i} init 0 range -1e30 1e30", f"field t{i} init 0 range -1e30 1e30", f"derive f{i} = {f}", f"derive t{i} = {t}"]
    law = os.path.join(work, "transposes.law")
    with open(law, "w") as fh:
        fh.write("\n".join(lines) + "\n")
    scene = write_scene(os.path.join(work, "t.scene"), (n[0], n[1], n[2], 1.0), [law])
    start = write_state(os.path.join(work, "t_init"), {"a": a, "b": b}, 1.0)
    out = os.path.join(work, f"t_out_{backend}")
    lawc("--scene", scene, "--init", start, "--steps", "1", "--dt", "0.1", "--backend", backend, "--dump", out, "--every", "1")
    got, _, _ = read_state(os.path.join(out, "step_1"))
    rows = []
    for i, (f, t) in enumerate(pairs):
        lhs = float(np.sum(got[f"f{i}"].astype(np.float64) * b))
        rhs = float(np.sum(a * got[f"t{i}"].astype(np.float64)))
        rows.append({"op": f.split("(")[0], "lhs": lhs, "rhs": rhs, "rel": abs(lhs - rhs) / max(abs(lhs), 1e-30)})
    return rows


def main():
    backends = ("cpu", "cuda") if cuda_available() else ("cpu",)
    results = {"transposes": {}}
    md = ["# Reverse mode in the IR\n\n`lawc --adjoint` generates a term's adjoint law from the IR (one reverse sweep over its "
          "SSA instructions); `lawc --vjp` runs the primal forward keeping every state, then the adjoint law backward. "
          "Everything below is the engine's own adjoint, on the backend named, against independent references.\n\n"]
    with tempfile.TemporaryDirectory() as work:
        # ---- transposes --------------------------------------------------------------------------------------------
        md.append("## Transposed stencils\n\n<op(a), b> against <a, op_t(b)>, random a and b on 7 x 6 x 5 (every edge):\n\n"
                  "| backend | op | <op(a), b> | <a, op_t(b)> | relative difference |\n|---|---|---|---|---|\n")
        for backend in backends:
            rows = transposes(work, backend)
            results["transposes"][backend] = rows
            for r in rows:
                md.append(f"| {backend} | {r['op']} | {r['lhs']:.6f} | {r['rhs']:.6f} | {r['rel']:.1e} |\n")
            print(f"transposes {backend}: worst {max(r['rel'] for r in rows):.1e}")
            assert max(r["rel"] for r in rows) < 1e-5

        # ---- Black-Scholes: the gradient, and vega and rho -------------------------------------------------------
        n = 512
        x, h = F.bs_grid(n)
        payoff = np.maximum(F.K - np.exp(x), 0.0)
        steps = F.bs_steps(h)
        dt = F.T / steps
        weights = np.zeros(n)
        j = int(np.searchsorted(x, math.log(100.0))) - 1
        f = (math.log(100.0) - x[j]) / h
        weights[j], weights[j + 1] = 1 - f, f  # L = V(ln 100) by the same linear read-out as finance.py
        grid = (n, 1, 1, h)
        start = write_state(os.path.join(work, "bs0"), {"V": payoff.reshape(1, 1, n), "P": payoff.reshape(1, 1, n)}, h)
        seed = write_state(os.path.join(work, "bs_seed"), {"V__adj": weights.reshape(1, 1, n)}, h)
        law = os.path.join(LAWS, "black_scholes.law")
        g_v, g_p = jax_grads(law, grid, {"V": payoff.reshape(1, 1, n), "P": payoff.reshape(1, 1, n)}, weights.reshape(1, 1, n),
                             {"lam": 0.0}, steps, dt, work, "V", ("sig", "r"))
        ref = F.bs_put_greeks(100.0)
        md.append(f"\n## Black-Scholes: dV(100)/d(everything) by one backward pass\n\n{n} cells, {steps} steps. Against jax.grad "
                  "through the twin (initial state and params) and the formula (vega, rho):\n\n"
                  "| backend | vega (total of sig__adj) | rho (total of r__adj) | vs jax.grad: dL/dV0, sig, r (relative) | vega, rho vs formula | forward, backward ms |\n"
                  "|---|---|---|---|---|---|\n")
        results["black_scholes"] = {"n": n, "steps": steps, "jax": {"sig": g_p["sig"], "r": g_p["r"]}, "formula": ref}
        for backend in backends:
            adj, line = run_vjp(law, grid, start, seed, {"lam": 0.0}, steps, dt, backend, work, "black_scholes")
            vega = float(np.sum(adj["sig__adj"].astype(np.float64)))
            rho = float(np.sum(adj["r__adj"].astype(np.float64)))
            d0 = rel(adj["V__adj"], g_v)
            times = line.split(": ", 1)[-1]
            results["black_scholes"][backend] = {"vega": vega, "rho": rho, "rel_dV0": d0, "rel_sig": abs(vega - g_p["sig"]) / abs(g_p["sig"]),
                                                 "rel_r": abs(rho - g_p["r"]) / abs(g_p["r"]), "timing": times}
            r = results["black_scholes"][backend]
            md.append(f"| {backend} | {vega:.5f} | {rho:.5f} | {d0:.1e}, {r['rel_sig']:.1e}, {r['rel_r']:.1e} | "
                      f"{abs(vega - ref['vega']) / ref['vega']:.1e}, {abs(rho - ref['rho']) / abs(ref['rho']):.1e} | {times} |\n")
            print(f"black-scholes {backend}: vega {vega:.5f} (jax {g_p['sig']:.5f}, formula {ref['vega']:.5f}), rho {rho:.5f} "
                  f"(jax {g_p['r']:.5f}, formula {ref['rho']:.5f}); dV0 vs jax {d0:.1e}")
            assert d0 < 1e-3 and r["rel_sig"] < 1e-3 and r["rel_r"] < 1e-3, r

        # ---- Heston (explicit): shifts, the mixed derivative, upwind switches ---------------------------------------
        p = {"sig_v": 0.3, "kappa": 1.5, "theta": 0.04, "rho": -0.9, "r": 0.025, "v0": 0.04, "vmax": 0.6}
        nx = 64
        hh = 6.0 / nx
        xs, vs, nx, ny = F.heston_grid(hh, p["vmax"], p["sig_v"])
        hsteps = int(math.ceil(F.T / F.heston_max_dt(hh, p, float(vs[-1]))))
        hdt = F.T / hsteps
        V0 = np.broadcast_to(np.maximum(F.K - np.exp(xs), 0.0)[None, :], (ny, nx)).reshape(1, ny, nx)
        var = np.broadcast_to(vs[:, None], (ny, nx)).reshape(1, ny, nx)
        rng = np.random.default_rng(5)
        w = rng.uniform(0.0, 1.0, (1, ny, nx))  # a loss that weighs every cell: the whole adjoint is checked
        params = {k: p[k] for k in ("sig_v", "kappa", "theta", "rho", "r")}
        params["var_max"] = float(vs[-1])
        hl = os.path.join(LAWS, "heston.law")
        hgrid = (nx, ny, 1, hh)
        hstart = write_state(os.path.join(work, "h0"), {"V": V0, "var": var}, hh)
        hseed = write_state(os.path.join(work, "h_seed"), {"V__adj": w}, hh)
        hg_v, hg_p = jax_grads(hl, hgrid, {"V": V0, "var": var}, w, params, hsteps, hdt, work, "V", ("kappa", "theta", "rho", "r", "sig_v"))
        md.append(f"\n## Heston (heston.law, explicit): every cell weighed\n\n{nx} x {ny} cells, {hsteps} steps, L = sum(w V_N) with "
                  "random w. Relative difference from jax.grad:\n\n| backend | dL/dV0 | kappa | theta | rho | r | sig_v (the law's own, var fixed) |\n"
                  "|---|---|---|---|---|---|---|\n")
        results["heston"] = {"nx": nx, "ny": ny, "steps": hsteps, "jax": hg_p}
        for backend in backends:
            adj, line = run_vjp(hl, hgrid, hstart, hseed, params, hsteps, hdt, backend, work, "heston")
            row = {"dV0": rel(adj["V__adj"], hg_v)}
            for k in ("kappa", "theta", "rho", "r", "sig_v"):
                row[k] = abs(float(np.sum(adj[k + "__adj"].astype(np.float64))) - hg_p[k]) / max(abs(hg_p[k]), 1e-30)
            row["timing"] = line.split(": ", 1)[-1]
            results["heston"][backend] = row
            md.append(f"| {backend} | {row['dV0']:.1e} | {row['kappa']:.1e} | {row['theta']:.1e} | {row['rho']:.1e} | {row['r']:.1e} | {row['sig_v']:.1e} |\n")
            print(f"heston {backend}: " + ", ".join(f"{k} {v:.1e}" for k, v in row.items() if k != "timing"))
            assert max(v for k, v in row.items() if k != "timing") < 1e-3, row

        # ---- cost on the card: 3-D heat ---------------------------------------------------------------------------
        if "cuda" in backends:
            n3, s3 = 128, 20
            dl = os.path.join(LAWS, "diffusion.law")
            h3 = 1.0 / n3
            T0 = (1.0 + np.random.default_rng(2).uniform(size=(n3, n3, n3))).astype(np.float32)
            start3 = write_state(os.path.join(work, "c0"), {"T": T0}, h3)
            seed3 = write_state(os.path.join(work, "c_seed"), {"T__adj": np.ones_like(T0)}, h3)
            dt3 = 0.99 * 0.15 * h3 * h3 / 0.01  # inside max_dt: one substep
            adj, line = run_vjp(dl, (n3, n3, n3, h3), start3, seed3, {}, s3, dt3, "cuda", work, "conduction")
            # sum(T_N) is conserved by the law, so dL/dT0 = 1 everywhere: what the adjoint must give back.
            err = float(np.max(np.abs(adj["T__adj"].astype(np.float64) - 1.0)))
            results["cost"] = {"n": n3, "steps": s3, "timing": line, "max_err_conserved": err}
            md.append(f"\n## Cost\n\n3-D heat (diffusion.law), {n3}³, {s3} steps on CUDA, L = sum(T_N) (conserved, so dL/dT0 is 1 "
                      f"everywhere: the adjoint gives it to {err:.1e}). {line.split(': ', 1)[-1]}: the backward pass includes "
                      "uploading each kept state (the primal states are kept on the host; no checkpointing yet).\n")
            print(f"cost: {line}; dL/dT0 - 1: {err:.1e}")
    # Without a card (CI) the results go to adjoint_cpu: the shipped adjoint.json keeps the CUDA rows.
    save("adjoint" if "cuda" in backends else "adjoint_cpu", results, "".join(md))


if __name__ == "__main__":
    os.chdir(BUILD)
    main()
